async function analyzePublicPage(btn){if(!fetched){toast('Primero consulta una página pública');return}if(btn)btn.disabled=true;$('aiResult').innerHTML='<div class="notice">Analizando sólo los datos de esta página…</div>';try{let result=await api('/api/public-page-ai',{model:$('openaiModel').value.trim(),snippet:fetched.snippet,title:fetched.title,url:fetched.url,candidate:{price:fetched.price,currency:fetched.currency},product:$('fetchProduct').value});let a=result.analysis;$('aiResult').innerHTML=`<div class="notice"><b>Revisión sugerida · ${esc(result.model||'OpenAI')}</b><br>Coincidencia: ${a.producto_coincide?'sí':'no / incierta'}<br>Producto: ${esc(a.producto_detectado||'Sin determinar')}<br>Precio: ${a.precio_detectado==null?'No confirmado':esc(a.precio_detectado)+' '+esc(a.moneda||'')} · Unidad: ${esc(a.unidad||'No identificada')}<br>Confianza: ${Math.round(Math.max(0,Math.min(1,Number(a.confianza)||0))*100)}%<br>${esc(a.observaciones||'')}</div>`}catch(e){$('aiResult').innerHTML=`<div class="notice warn">${esc(e.message)}</div>`}finally{if(btn)btn.disabled=false}}
async function saveFetchedPrice(){try{await api('/api/prices',{seller:$('fetchSeller').value,product:$('fetchProduct').value,price:$('fetchAmount').value,currency:$('fetchCurrency').value,unit:$('fetchUnit').value,url:$('fetchUrl').value,verified:true});toast('Precio confirmado y guardado');$('fetchConfirm').style.display='none';$('fetchMsg').innerHTML='';loadAll()}catch(e){toast(e.message)}}
async function loadMarketAutomation(){try{let c=await api('/api/market-automation');$('mlClientId').value=c.client_id||'';$('mlRedirectUri').value=c.redirect_uri||'https://www.mercadolibre.cl';$('marketEnabled').checked=!!c.enabled;$('marketTime').value=c.time||'10:00';let oficio=[...$('autoProduct2').options].find(o=>o.value.toLowerCase().includes('oficio'));if(oficio&&!(c.queries||[]).length)$('autoProduct2').value=oficio.value;if(c.queries?.length){$('autoProduct1').value=c.queries[0].product||$('autoProduct1').value;$('autoQuery1').value=c.queries[0].query||'';if(c.queries[1]){$('autoProduct2').value=c.queries[1].product||$('autoProduct2').value;$('autoQuery2').value=c.queries[1].query||''}}$('mlAuthStatus').className='notice';$('mlAuthStatus').textContent=c.connected?'MercadoLibre conectado. Los tokens no se muestran y se renuevan automáticamente.':'MercadoLibre aún no está conectado.';$('marketStatus').className=c.enabled&&c.connected?'notice':'notice warn';$('marketStatus').textContent=`${c.enabled?'Consultas diarias activas':'Consultas diarias apagadas'} · ${c.last_run?'última ejecución: '+c.last_run:'sin ejecución registrada'} · ${c.last_count||0} registro(s) · ${c.last_status||'sin novedades'}`}catch(e){$('marketStatus').className='notice warn';$('marketStatus').textContent=e.message}}
