async function runMarketNow(){let btn=document.querySelector('#prices button[onclick="runMarketNow()"]');if(btn)btn.disabled=true;$('marketStatus').textContent='Consultando MercadoLibre y guardando anuncios por revisar…';try{let r=await api('/api/market-automation/run-now',{});toast(`${r.saved} registro(s) nuevos o actualizados`);loadAll();loadMarketAutomation()}catch(e){$('marketStatus').className='notice warn';$('marketStatus').textContent=e.message}finally{if(btn)btn.disabled=false}}
