async function saveProduct(){try{if(!$('pName').value.trim())throw Error('Escribe un nombre de producto');await api('/api/products',{name:$('pName').value.trim(),spec:$('pSpec').value,unit:$('pUnit').value||'unidad'});$('pName').value='';$('pSpec').value='';toast('Producto agregado');loadAll()}catch(e){toast(e.message)}}
async function parseEmailFile(){const f=$('emlFile').files[0];if(!f){toast('Elige un archivo .eml');return}try{let raw=await f.text();let data=await api('/api/email-parse',{raw});currentEmailReviewId=null;$('eSupplier').value=data.sender||'';$('eProduct').value=data.product||'';$('ePrice').value=data.unit_price??'';$('eCurrency').value=data.currency||'USD';$('eMoq').value=data.moq||'';$('eIncoterm').value=data.incoterm||'';$('ePayment').value=data.payment_terms||'';$('eNotes').value=[data.subject,(data.attachments||[]).length?'Adjuntos: '+data.attachments.join(', '):'',...(data.attachment_issues||[])].filter(Boolean).join(' · ');$('emailReview').style.display='block';$('emailMsg').innerHTML='<div class="notice">Revisa los valores detectados. El correo y sus adjuntos originales no se guardaron.</div>'}catch(e){$('emailMsg').innerHTML=`<div class="notice error">${esc(e.message)}</div>`}}
async function loadImapConfig(){try{let c=await api('/api/imap-config');$('imapHost').value=c.host;$('imapPort').value=c.port;$('imapUser').value=c.username;$('imapTime').value=c.time||'10:00';$('imapEnabled').checked=!!c.enabled;$('imapPassword').value='';$('imapMsg').className=c.configured&&c.enabled?'notice':'notice warn';$('imapMsg').textContent=`${c.configured?'Contraseña guardada cifrada':'Falta guardar la contraseña'}${c.secret_scope==='machine'?' · cifrado Windows de equipo':''} · ${c.enabled?'revisión diaria activa':'revisión automática apagada'} · ${c.last_run?'última revisión: '+c.last_run:'sin revisión registrada'} · ${c.last_status||''}`}catch(e){$('imapMsg').className='notice error';$('imapMsg').textContent=e.message}}
function imapPayload(){return {host:$('imapHost').value,port:$('imapPort').value,username:$('imapUser').value,time:$('imapTime').value,enabled:$('imapEnabled').checked,password:$('imapPassword').value}}
async function saveImapConfig(){try{let c=await api('/api/imap-config',imapPayload());$('imapPassword').value='';$('imapMsg').className=c.enabled&&c.configured?'notice':'notice warn';$('imapMsg').textContent=`Configuración guardada cifrada${c.secret_scope==='machine'?' con protección de equipo':''} · ${c.enabled?'revisión diaria activa':'revisión automática apagada'}. Importex analizará los nuevos mensajes de Entrada y Enviados.`;toast('Configuración IMAP guardada')}catch(e){$('imapMsg').className='notice error';$('imapMsg').textContent=e.message}}
async function scanMailbox(){ $('imapMsg').className='notice';$('imapMsg').textContent='Guardando configuración cifrada y revisando Entrada y Enviados…';try{await api('/api/imap-config',imapPayload());$('imapPassword').value='';let result=await api('/api/imap-scan-now',{});await loadEmailReviews();await loadImapConfig();if(result.status){$('imapMsg').className='notice warn';$('imapMsg').textContent=result.status}else if(result.baseline){$('imapMsg').className='notice warn';$('imapMsg').textContent=`Punto de partida guardado. No se importaron correos antiguos. Carpetas detectadas: ${(result.baseline_folders||[]).join(', ')||'Entrada'}.${result.sent_folder_found?' Enviados detectado.':' No se detectó Enviados; se revisó sólo Entrada.'}`}else{$('imapMsg').className=result.sent_folder_found?'notice':'notice warn';$('imapMsg').textContent=`${result.saved||0} correo(s) nuevo(s) guardado(s) “Por revisar”. ${result.sent_folder_found?'Se revisaron Entrada y Enviados.':'No se encontró carpeta Enviados; se revisó sólo Entrada.'} El buzón no se modificó.`}}catch(e){$('imapPassword').value='';$('imapMsg').className='notice error';$('imapMsg').textContent=e.message}}
async function loadEmailReviews(){try{emailReviews=await api('/api/email-reviews');$('imapTable').innerHTML=emailReviews.length?`<div class="table-wrap"><table><thead><tr><th>Fecha</th><th>Carpeta</th><th>Remitente</th><th>Asunto</th><th>Precio detectado</th><th>Estado / acciones</th></tr></thead><tbody>${emailReviews.map((r,i)=>`<tr><td>${esc((r.message_date||r.captured_at||'').slice(0,25))}</td><td>${esc(r.parsed?.mailbox_folder||'Archivo .eml')}</td><td>${esc(r.sender)}</td><td>${esc(r.subject||'Sin asunto')}</td><td>${r.parsed?.unit_price?fmt(r.parsed.unit_price,r.parsed.currency):'No detectado'}</td><td><div class="actions"><button class="btn secondary" onclick="reviewSavedEmail(${i})">Revisar</button><button class="btn ghost" onclick="ignoreEmailReview(${r.id})">Descartar</button></div></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No hay correos pendientes de revisión. Al activar IMAP, Importex analizará los nuevos mensajes de Entrada y Enviados.</div>'}catch(e){$('imapTable').innerHTML=`<div class="notice error">${esc(e.message)}</div>`}}
function reviewSavedEmail(i){let r=emailReviews[i],m=r?.parsed;if(!r||!m)return;currentEmailReviewId=r.id;$('eSupplier').value=m.sender||r.sender||'';$('eProduct').value=m.product||'';$('ePrice').value=m.unit_price??'';$('eCurrency').value=m.currency||'USD';$('eMoq').value=m.moq||'';$('eIncoterm').value=m.incoterm||'';$('ePayment').value=m.payment_terms||'';$('eNotes').value=[r.subject,r.message_date,m.notes].filter(Boolean).join(' · ');$('emailReview').style.display='block';$('emailReview').scrollIntoView({behavior:'smooth',block:'start'})}
async function ignoreEmailReview(id){if(!confirm('¿Descartar esta cotización de la bandeja pendiente?'))return;try{await api('/api/email-reviews/'+id+'/ignore',{});await loadEmailReviews();toast('Cotización descartada')}catch(e){toast(e.message)}}
async function saveEmailQuote(){try{let payload={supplier:$('eSupplier').value,product:$('eProduct').value,unit_price:$('ePrice').value,currency:$('eCurrency').value,moq:$('eMoq').value,incoterm:$('eIncoterm').value,payment_terms:$('ePayment').value,notes:$('eNotes').value};if(currentEmailReviewId)await api('/api/email-reviews/'+currentEmailReviewId+'/approve',payload);else await api('/api/quotes',payload);toast('Cotización confirmada y guardada');$('emailReview').style.display='none';$('emlFile').value='';currentEmailReviewId=null;await Promise.all([loadAll(),loadEmailReviews()])}catch(e){toast(e.message)}}
function calculate(){try{let required=['cFob','cFx','cFreight','cInsurance','cDuty','cLocal','cSell','cFixed','cUsdClp'];if(required.some(id=>$(id).value.trim()===''))throw Error('Completa las cotizaciones y supuestos pendientes; el panel no estima valores que aún no tienes.');let qty=+$('cQty').value,fx=+$('cFx').value,fob=+$('cFob').value,freight=+$('cFreight').value,ins=+$('cInsurance').value,dutyPercent=+$('cDuty').value,local=+$('cLocal').value,vatPercent=+$('cVat').value,clp=+$('cUsdClp').value,sell=+$('cSell').value,fixed=+$('cFixed').value,pack=+$('cPack').value,cur=$('cCurrency').value,basis=$('cBasis').value;let nums=[qty,fx,fob,freight,ins,dutyPercent,local,vatPercent,clp,sell,fixed,pack];if(nums.some(n=>!Number.isFinite(n)||n<0)||qty<=0||fob<=0||fx<=0||clp<=0||pack<=0||dutyPercent>100||vatPercent>100)throw Error('Hay datos vacíos o fuera de rango');let dutyRate=dutyPercent/100,vat=vatPercent/100,unitFob=basis==='case'?fob/pack:fob,unitUsd=cur==='USD'?unitFob:cur==='CLP'?unitFob/clp:unitFob/fx;let fobTotal=unitUsd*qty,cif=fobTotal+freight+ins,duty=cif*dutyRate,vatCash=(cif+duty)*vat,landedNet=(cif+duty+local)/qty,cashUnit=landedNet+vatCash/qty,landedClp=landedNet*clp,sellUsd=sell/clp,contribution=sellUsd-landedNet,markup=landedNet?contribution/landedNet:0,margin=sellUsd?contribution/sellUsd:0,be=contribution>0?fixed/clp/contribution:Infinity;let ids=['cProduct','cQty','cFob','cCurrency','cBasis','cPack','cFx','cFreight','cInsurance','cDuty','cLocal','cVat','cSell','cFixed','cUsdClp'];let inputs=Object.fromEntries(ids.map(id=>[id,$(id).value]));lastCalc={qty,unitUsd,cif,duty,landedNet,vatCash,landedClp,cashUnit,sell,contribution,markup,margin,be,clp,inputs};$('calcOutput').innerHTML=`<div class="result"><div><span>FOB total</span><b>${fmt(fobTotal,'USD')}</b></div><div><span>CIF total estimado</span><b>${fmt(cif,'USD')}</b></div><div><span>Derechos estimados</span><b>${fmt(duty,'USD')}</b></div><div><span>Costo neto por unidad</span><b>${fmt(landedClp,'CLP')}</b></div><div><span>IVA de importación: caja</span><b>${fmt(vatCash,'USD')}</b></div><div><span>Costo caja/unidad con IVA</span><b>${fmt(cashUnit*clp,'CLP')}</b></div><div><span>Contribución por unidad</span><b>${fmt(contribution*clp,'CLP')}</b></div><div><span>Markup sobre costo neto</span><b>${(markup*100).toFixed(1)}%</b></div><div><span>Margen bruto sobre venta neta</span><b>${(margin*100).toFixed(1)}%</b></div><div><span>Equilibrio aproximado</span><b>${Number.isFinite(be)?Math.ceil(be).toLocaleString('es-CL')+' un.':'No alcanza'}</b></div></div><div class="notice ${contribution>0?'':'warn'}">${contribution>0?'El escenario muestra contribución positiva antes de costos variables no incluidos, impuestos a la renta y diferencias de tipo de cambio.':'Con estos supuestos, el precio de venta no cubre el costo neto estimado.'}</div>`;renderPlan()}catch(e){toast(e.message||'Revisa los datos numéricos')}}
async function saveScenario(){if(!lastCalc){toast('Calcula primero el escenario');return}let name=$('scenarioName').value.trim();if(!name){toast('Escribe un nombre para este escenario');$('scenarioName').focus();return}try{await api('/api/scenarios',{name,product:lastCalc.inputs.cProduct,inputs:lastCalc.inputs,result:lastCalc});await loadAll();toast('Escenario guardado en este equipo')}catch(e){toast(e.message)}}
function loadScenario(){let s=savedScenarios.find(x=>String(x.id)===$('scenarioSelect').value);if(!s){toast('Elige un escenario guardado');return}Object.entries(s.inputs).forEach(([id,value])=>{if($(id))$(id).value=value});$('scenarioName').value=s.name;calculate();toast('Escenario cargado')}
async function deleteScenario(){let id=$('scenarioSelect').value;if(!id){toast('Elige un escenario guardado');return}try{await deleteApi('/api/scenarios/'+encodeURIComponent(id));await loadAll();$('calcOutput').innerHTML='<div class="empty">Completa los datos y calcula.</div>';lastCalc=null;toast('Escenario eliminado')}catch(e){toast(e.message)}}
function renderPlan(){let d=lastCalc||JSON.parse(localStorage.getItem('comercio_last_scenario')||'null');if(!d)return;let net=d.contribution*d.clp, units=Number.isFinite(d.be)?Math.ceil(d.be):0;$('planOutput').innerHTML=`<div class="result"><div><span>Contribución/unidad</span><b>${fmt(net,'CLP')}</b></div><div><span>Unidades para equilibrio</span><b>${units.toLocaleString('es-CL')}</b></div><div><span>Reserva de reinversión</span><b>40% utilidad cobrada</b></div></div><p class="footnote">Este resultado usa el último escenario, no ventas reales. La utilidad retenida se calcula sólo después de cubrir el ciclo de reposición y obligaciones.</p>`;let months=[['1–2','Validar demanda y cotizaciones',0],['3','Piloto local',120],['4','Decidir compra internacional',300],['5','Carga en tránsito',450],['6','Primeras ventas importadas',700],['7','Recompra condicionada',900],['8','Ajustar precio y mezcla',1100],['9','Meta: equilibrio',units],['10','Reinvertir parte de utilidad cobrada',units],['11','Evaluar segundo canal',units],['12','Escalar sólo con rotación',units]];$('monthlyPlan').innerHTML=`<div class="table-wrap"><table><thead><tr><th>Mes</th><th>Hito</th><th>Unidades de referencia</th><th>40% reinversión</th></tr></thead><tbody>${months.map(([m,h,u])=>`<tr><td>${m}</td><td>${h}</td><td>${Number(u).toLocaleString('es-CL')}</td><td>${m==='1–2'||m==='3'?'—':'Se calcula sobre utilidad neta cobrada'}</td></tr>`).join('')}</tbody></table></div>`}
 $('today').textContent=new Intl.DateTimeFormat('es-CL',{dateStyle:'long'}).format(new Date());
async function loadAlertConfig(){try{let c=await api('/api/alerts');$('smtpHost').value=c.host;$('smtpPort').value=String(c.port);$('smtpSecurity').value=c.security;$('smtpUser').value=c.username;$('smtpSender').value=c.sender;$('smtpRecipient').value=c.recipient;$('alertEnabled').checked=c.enabled;$('alertTime').value=c.time;$('alertStatus').className='notice';$('alertStatus').textContent=c.configured?`Correo configurado${c.enabled?' · alertas activas':' · alertas apagadas'}${c.last_sent?' · último envío: '+c.last_sent:''}. La clave no se puede recuperar desde el panel.`:'Configura el correo y guarda la contraseña cifrada para activar las alertas.'}catch(e){$('alertStatus').className='notice error';$('alertStatus').textContent=e.message}}
async function saveAlertConfig(){let payload={host:$('smtpHost').value,port:$('smtpPort').value,security:$('smtpSecurity').value,username:$('smtpUser').value,sender:$('smtpSender').value,recipient:$('smtpRecipient').value,time:$('alertTime').value,enabled:$('alertEnabled').checked,password:$('smtpPassword').value};try{let c=await api('/api/alerts/config',payload);$('smtpPassword').value='';$('alertStatus').className='notice';$('alertStatus').textContent=`Configuración guardada${c.enabled?' y alertas activas':' · alertas apagadas'}. Usa “Enviar correo de prueba” para comprobar la conexión.`}catch(e){$('alertStatus').className='notice error';$('alertStatus').textContent=e.message}}
async function sendAlertTest(){if(!confirm('¿Enviar un correo de prueba a '+$('smtpRecipient').value+'?'))return;try{await api('/api/alerts/test',{});$('alertStatus').className='notice';$('alertStatus').textContent='Correo de prueba enviado. Revisa la bandeja de entrada y spam.'}catch(e){$('alertStatus').className='notice error';$('alertStatus').textContent='No se pudo enviar: '+e.message}}
const initialPage=location.hash&&titles[location.hash.slice(1)]?location.hash.slice(1):'home';go(initialPage);
